+    [string]$MarkdownOut = "reports/01-inventory.md",
+    [string]$LogOut = "logs/01-inventory.md"
+)
+
+$ErrorActionPreference = "Stop"
+
+function Get-RelativePath {
+    param(
+        [string]$BasePath,
+        [string]$TargetPath
+    )
+
+    $base = [System.IO.Path]::GetFullPath($BasePath)
+    if (-not $base.EndsWith([System.IO.Path]::DirectorySeparatorChar)) {
+        $base += [System.IO.Path]::DirectorySeparatorChar
+    }
+
+    $baseUri = [System.Uri]$base
+    $targetUri = [System.Uri]([System.IO.Path]::GetFullPath($TargetPath))
+    $relative = $baseUri.MakeRelativeUri($targetUri).ToString()
+    return [System.Uri]::UnescapeDataString($relative).Replace('/', '\')
+}
+
+function New-NormalizedKey {
+    param([string]$Text)
+
+    if ([string]::IsNullOrWhiteSpace($Text)) {
+        return ""
+    }
+
+    $normalized = $Text.Normalize([Text.NormalizationForm]::FormD)
+    $sb = New-Object System.Text.StringBuilder
+    foreach ($ch in $normalized.ToCharArray()) {
+        $category = [Globalization.CharUnicodeInfo]::GetUnicodeCategory($ch)
+        if ($category -ne [Globalization.UnicodeCategory]::NonSpacingMark) {
+            [void]$sb.Append($ch)
+        }
+    }
+
+    $result = $sb.ToString().Normalize([Text.NormalizationForm]::FormC).ToLowerInvariant()
+    $result = [regex]::Replace($result, "\s+", " ").Trim()
+    return $result
+}
+
+function Resolve-WikiLinkCandidates {
+    param(
+        [string]$LinkTarget,
+        [string]$CurrentDirectory,
+        [System.Collections.Generic.HashSet[string]]$MarkdownPathSet,
+        [hashtable]$StemIndex
+    )
+
+    $coreTarget = $LinkTarget.Split("#")[0].Split("|")[0].Trim()
+    if ([string]::IsNullOrWhiteSpace($coreTarget)) {
+        return @()
+    }
+
+    $candidates = New-Object System.Collections.Generic.List[string]
+    $pathVariant = $coreTarget.Replace('/', '\')
+
+    if ($pathVariant -match '\.[^\\\/]+$') {
+        $candidatePath = [System.IO.Path]::GetFullPath((Join-Path $CurrentDirectory $pathVariant))
+        if ($MarkdownPathSet.Contains($candidatePath)) {
+            $candidates.Add($candidatePath)
+        }
+    } else {
+        $candidatePath = [System.IO.Path]::GetFullPath((Join-Path $CurrentDirectory ($pathVariant + ".md")))
+        if ($MarkdownPathSet.Contains($candidatePath)) {
+            $candidates.Add($candidatePath)
+        }
+
+        $leaf = Split-Path $pathVariant -Leaf
+        $normalizedLeaf = New-NormalizedKey $leaf
+        if ($StemIndex.ContainsKey($normalizedLeaf)) {
+            foreach ($match in $StemIndex[$normalizedLeaf]) {
+                if (-not $candidates.Contains($match)) {
+                    $candidates.Add($match)
+                }
+            }
+        }
+    }
+
+    return $candidates
+}
+
+function Resolve-MarkdownLink {
+    param(
+        [string]$LinkTarget,
+        [string]$CurrentDirectory
+    )
+
+    $coreTarget = $LinkTarget.Split("#")[0].Trim()
+    if ([string]::IsNullOrWhiteSpace($coreTarget)) {
+        return $null
+    }
+
+    if ($coreTarget -match '^(https?|mailto|obsidian):') {
+        return $null
+    }
+
+    return [System.IO.Path]::GetFullPath((Join-Path $CurrentDirectory $coreTarget.Replace('/', '\')))
+}
+
+$rootPath = [System.IO.Path]::GetFullPath($Root)
+$timestamp = Get-Date -Format o
+$excludedNames = @(".git", ".agents", "reports", "logs", "scripts", "_staging", "_archive_review", "_merge_candidates")
+$excludedSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
+foreach ($name in $excludedNames) {
+    [void]$excludedSet.Add($name)
+}
+
+$allFiles = Get-ChildItem -LiteralPath $rootPath -Recurse -Force -File | Where-Object {
+    $segments = Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName -split '[\\/]'
+    -not ($segments | Where-Object { $excludedSet.Contains($_) })
+}
+
+$allDirectories = Get-ChildItem -LiteralPath $rootPath -Recurse -Force -Directory | Where-Object {
+    $segments = Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName -split '[\\/]'
+    -not ($segments | Where-Object { $excludedSet.Contains($_) })
+}
+
+$markdownFiles = @($allFiles | Where-Object { $_.Extension -ieq ".md" })
+$markdownPathSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
+$stemIndex = @{}
+
+foreach ($file in $markdownFiles) {
+    [void]$markdownPathSet.Add($file.FullName)
+    $normalizedStem = New-NormalizedKey $file.BaseName
+    if (-not $stemIndex.ContainsKey($normalizedStem)) {
+        $stemIndex[$normalizedStem] = New-Object System.Collections.Generic.List[string]
+    }
+    $stemIndex[$normalizedStem].Add($file.FullName)
+}
+
+$inventoryByFolder = $allFiles |
+    Group-Object { Split-Path (Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName) -Parent } |
+    Sort-Object Count -Descending |
+    ForEach-Object {
+        [PSCustomObject]@{
+            path = if ([string]::IsNullOrWhiteSpace($_.Name)) { "." } else { $_.Name }
+            file_count = $_.Count
+            markdown_count = @($_.Group | Where-Object { $_.Extension -ieq ".md" }).Count
+        }
+    }
+
+$inventoryByExtension = $allFiles |
+    Group-Object { if ([string]::IsNullOrWhiteSpace($_.Extension)) { "[no extension]" } else { $_.Extension.ToLowerInvariant() } } |
+    Sort-Object Count -Descending |
+    ForEach-Object {
+        [PSCustomObject]@{
+            extension = $_.Name
+            count = $_.Count
+        }
+    }
+
+$subVaults = @(
+    Get-ChildItem -LiteralPath $rootPath -Recurse -Force -Directory -Filter ".obsidian" | ForEach-Object {
+        [PSCustomObject]@{
+            obsidian_path = Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName
+            vault_root = Get-RelativePath -BasePath $rootPath -TargetPath $_.Parent.FullName
+        }
+    }
+)
+
+$trashDirectories = @(
+    $allDirectories | Where-Object { $_.Name -match '^(?i)\.trash$' -or $_.Name -match '(?i)trash' } | ForEach-Object {
+        [PSCustomObject]@{
+            path = Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName
+            file_count = @(Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue).Count
+        }
+    }
+)
+
+$genericNameRegex = '^(untitled(\s*\d*)?|sem titulo(\s*\d*)?|nova nota(\s*\d*)?|new note(\s*\d*)?|documento(\s*\d*)?|copy(\s*\d*)?|copia(\s*\d*)?|teste(\s*\d*)?|test(\s*\d*)?|final(\s*\d*)?)$'
+$genericOrUntitledFiles = @(
+    $allFiles | Where-Object {
+        $stem = $_.BaseName.Trim()
+        [string]::IsNullOrWhiteSpace($stem) -or ((New-NormalizedKey $stem) -match $genericNameRegex)
+    } | ForEach-Object {
+        [PSCustomObject]@{
+            path = Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName
+            size = $_.Length
+        }
+    }
+)
+
+$mirrorKeywords = @("clone", "clones", "copy", "copia", "backup", "mirror", "espelho", "import", "imports", "importado", "importados", "drive", "not synced", "archive", "arquivo", "arquivos")
+$mirrorAreas = @(
+    $allDirectories | Where-Object {
+        $relative = Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName
+        $normalized = New-NormalizedKey $relative
+        $mirrorKeywords | Where-Object { $normalized -like "*$_*" }
+    } | ForEach-Object {
+        [PSCustomObject]@{
+            path = Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName
+            markdown_count = @(Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -Filter *.md -ErrorAction SilentlyContinue).Count
+        }
+    }
+)
+
+$duplicateNameGroups = @(
+    $markdownFiles |
+    Group-Object { New-NormalizedKey $_.BaseName } |
+    Where-Object { $_.Count -gt 1 -and -not [string]::IsNullOrWhiteSpace($_.Name) } |
+    Sort-Object Count -Descending |
+    Select-Object -First 25 |
+    ForEach-Object {
+        [PSCustomObject]@{
+            normalized_name = $_.Name
+            count = $_.Count
+            sample_paths = @($_.Group | Select-Object -First 5 | ForEach-Object {
+                Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName
+            })
+        }
+    }
+)
+
+$incomingLinks = @{}
+$unresolvedLinks = New-Object System.Collections.Generic.List[object]
+$resolvedLinkCount = 0
+$wikiLinkCount = 0
+$markdownLinkCount = 0
+
+foreach ($file in $markdownFiles) {
+    $relativePath = Get-RelativePath -BasePath $rootPath -TargetPath $file.FullName
+    $content = Get-Content -LiteralPath $file.FullName -Raw -ErrorAction SilentlyContinue
+    if ($null -eq $content) {
+        continue
+    }
+
+    $currentDir = Split-Path $file.FullName -Parent
+
+    $wikiMatches = [regex]::Matches($content, '\[\[([^\]]+)\]\]')
+    foreach ($match in $wikiMatches) {
+        $wikiLinkCount++
+        $target = $match.Groups[1].Value
+        $candidates = Resolve-WikiLinkCandidates -LinkTarget $target -CurrentDirectory $currentDir -MarkdownPathSet $markdownPathSet -StemIndex $stemIndex
+        if ($candidates.Count -gt 0) {
+            $resolvedLinkCount++
+            foreach ($candidate in $candidates | Select-Object -Unique) {
+                if (-not $incomingLinks.ContainsKey($candidate)) {
+                    $incomingLinks[$candidate] = 0
+                }
+                $incomingLinks[$candidate]++
+            }
+        } else {
+            $unresolvedLinks.Add([PSCustomObject]@{
+                source = $relativePath
+                type = "wikilink"
+                target = $target
+            })
+        }
+    }
+
+    $mdMatches = [regex]::Matches($content, '(?<!!)\[[^\]]+\]\(([^)]+)\)')
+    foreach ($match in $mdMatches) {
+        $markdownLinkCount++
+        $target = $match.Groups[1].Value.Trim()
+        $resolved = Resolve-MarkdownLink -LinkTarget $target -CurrentDirectory $currentDir
+        if ($null -eq $resolved) {
+            continue
+        }
+
+        if (Test-Path -LiteralPath $resolved) {
+            $resolvedLinkCount++
+            if ([System.IO.Path]::GetExtension($resolved) -ieq ".md") {
+                if (-not $incomingLinks.ContainsKey($resolved)) {
+                    $incomingLinks[$resolved] = 0
+                }
+                $incomingLinks[$resolved]++
+            }
+        } else {
+            $unresolvedLinks.Add([PSCustomObject]@{
+                source = $relativePath
+                type = "markdown"
+                target = $target
+            })
+        }
+    }
+}
+
+$orphanCandidates = @(
+    $markdownFiles | Where-Object {
+        $relative = Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName
+        $normalizedRelative = New-NormalizedKey $relative
+        $normalizedStem = New-NormalizedKey $_.BaseName
+        $incomingCount = if ($incomingLinks.ContainsKey($_.FullName)) { $incomingLinks[$_.FullName] } else { 0 }
+        $looksStructural = $normalizedRelative -like "*diario*" -or
+            $normalizedRelative -like "*template*" -or
+            $normalizedStem -match '^\d{4}$' -or
+            $normalizedStem -match '^\d{2}\s*-' -or
+            $normalizedStem -eq "readme" -or
+            $normalizedStem -eq "diario"
+        $incomingCount -eq 0 -and -not $looksStructural
+    } | ForEach-Object {
+        [PSCustomObject]@{
+            path = Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName
+            size = $_.Length
+        }
+    }
+)
+
+$reportObject = [PSCustomObject]@{
+    generated_at = $timestamp
+    root = $rootPath
+    exclusions = $excludedNames
+    totals = [PSCustomObject]@{
+        file_count = $allFiles.Count
+        directory_count = $allDirectories.Count
+        markdown_count = $markdownFiles.Count
+        sub_vault_count = $subVaults.Count
+        trash_directory_count = $trashDirectories.Count
+        generic_or_untitled_count = $genericOrUntitledFiles.Count
+        mirror_area_count = $mirrorAreas.Count
+        orphan_candidate_count = $orphanCandidates.Count
+        unresolved_link_count = $unresolvedLinks.Count
+        resolved_link_count = $resolvedLinkCount
+        wiki_link_count = $wikiLinkCount
+        markdown_link_count = $markdownLinkCount
+    }
+    inventory_by_folder = $inventoryByFolder
+    inventory_by_extension = $inventoryByExtension
+    sub_vaults = $subVaults
+    trash_directories = $trashDirectories
+    generic_or_untitled_files = $genericOrUntitledFiles
+    mirror_areas = $mirrorAreas
+    duplicate_note_names = $duplicateNameGroups
+    orphan_candidates = $orphanCandidates
+    unresolved_links = $unresolvedLinks
+}
+
+$jsonDir = Split-Path $JsonOut -Parent
+$mdDir = Split-Path $MarkdownOut -Parent
+$logDir = Split-Path $LogOut -Parent
+foreach ($dir in @($jsonDir, $mdDir, $logDir)) {
+    if (-not [string]::IsNullOrWhiteSpace($dir)) {
+        New-Item -ItemType Directory -Force -Path (Join-Path $rootPath $dir) | Out-Null
+    }
+}
+
+$reportObject | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $rootPath $JsonOut) -Encoding UTF8
+
