$excludedNames = @(".git", ".agents", "reports", "logs", "scripts", "_staging", "_archive_review", "_merge_candidates")
$excludedSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
foreach ($name in $excludedNames) {
    [void]$excludedSet.Add($name)
}

$allFiles = Get-ChildItem -LiteralPath $rootPath -Recurse -Force -File | Where-Object {
    $segments = Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName -split '[\\/]'
    -not ($segments | Where-Object { $excludedSet.Contains($_) })
}

$allDirectories = Get-ChildItem -LiteralPath $rootPath -Recurse -Force -Directory | Where-Object {
    $segments = Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName -split '[\\/]'
    -not ($segments | Where-Object { $excludedSet.Contains($_) })
}

$markdownFiles = @($allFiles | Where-Object { $_.Extension -ieq ".md" })
$markdownPathSet = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
$stemIndex = @{}

foreach ($file in $markdownFiles) {
    [void]$markdownPathSet.Add($file.FullName)
    $normalizedStem = New-NormalizedKey $file.BaseName
    if (-not $stemIndex.ContainsKey($normalizedStem)) {
        $stemIndex[$normalizedStem] = New-Object System.Collections.Generic.List[string]
    }
    $stemIndex[$normalizedStem].Add($file.FullName)
}

$inventoryByFolder = $allFiles |
