            file_count = @(Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue).Count
        }
    }
)

$genericNameRegex = '^(untitled(\s*\d*)?|sem titulo(\s*\d*)?|nova nota(\s*\d*)?|new note(\s*\d*)?|documento(\s*\d*)?|copy(\s*\d*)?|copia(\s*\d*)?|teste(\s*\d*)?|test(\s*\d*)?|final(\s*\d*)?)$'
$genericOrUntitledFiles = @(
    $allFiles | Where-Object {
        $stem = $_.BaseName.Trim()
        [string]::IsNullOrWhiteSpace($stem) -or ((New-NormalizedKey $stem) -match $genericNameRegex)
    } | ForEach-Object {
        [PSCustomObject]@{
            path = Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName
            size = $_.Length
        }
    }
)

$mirrorKeywords = @("clone", "clones", "copy", "copia", "backup", "mirror", "espelho", "import", "imports", "importado", "importados", "drive", "not synced", "archive", "arquivo", "arquivos")
$mirrorAreas = @(
    $allDirectories | Where-Object {
        $relative = Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName
        $normalized = New-NormalizedKey $relative
        $mirrorKeywords | Where-Object { $normalized -like "*$_*" }
    } | ForEach-Object {
        [PSCustomObject]@{
            path = Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName
            markdown_count = @(Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -Filter *.md -ErrorAction SilentlyContinue).Count
        }
    }
)

$duplicateNameGroups = @(
    $markdownFiles |
    Group-Object { New-NormalizedKey $_.BaseName } |
    Where-Object { $_.Count -gt 1 -and -not [string]::IsNullOrWhiteSpace($_.Name) } |
    Sort-Object Count -Descending |
    Select-Object -First 25 |
    ForEach-Object {
        [PSCustomObject]@{
            normalized_name = $_.Name
            count = $_.Count
            sample_paths = @($_.Group | Select-Object -First 5 | ForEach-Object {
                Get-RelativePath -BasePath $rootPath -TargetPath $_.FullName
            })
        }
    }
)

